-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.report_limits()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object('per_day', 50, 'open_per_place', 5);
$function$;

grant execute on function public.report_limits() to authenticated;
grant execute on function public.report_limits() to service_role;
